const certificateDialog=document.getElementById('certificate-dialog');let activeCertificate=0;let activeCertificateFilter='all';let viewerCertificateIndices=null;
function visibleCertificates(){return certificateData.map((c,i)=>({c,i})).filter(({c})=>activeCertificateFilter==='all'||c.group===activeCertificateFilter).map(({i})=>i)}
function displayCertificate(index,scope){if(scope)viewerCertificateIndices=scope;activeCertificate=index;const c=certificateData[index];const img=document.getElementById('certificate-large');img.src=`assets/certificates/${c.slug}.jpg`;img.alt=`${c.title} certificate awarded to Fouad Abdulhakeem`;document.getElementById('certificate-title').textContent=c.title;document.getElementById('certificate-kind').textContent=c.kind;document.getElementById('certificate-issuer').textContent=`${c.issuer} · ${c.date}`;const link=document.getElementById('certificate-verification');link.href=c.verification;link.textContent=c.verificationLabel+' ↗';const visible=viewerCertificateIndices||visibleCertificates();document.getElementById('certificate-position').textContent=`MY CERTIFICATE COLLECTION / ${visible.indexOf(index)+1} OF ${visible.length}`;document.getElementById('previous-certificate').disabled=visible.length===1;document.getElementById('next-certificate').disabled=visible.length===1}
function stepCertificate(dir){const visible=viewerCertificateIndices||visibleCertificates();displayCertificate(visible[(visible.indexOf(activeCertificate)+dir+visible.length)%visible.length])}
document.querySelectorAll('[data-cert-preview]').forEach(b=>b.addEventListener('click',()=>{displayCertificate(Number(b.dataset.certPreview),visibleCertificates());certificateDialog.showModal()}));document.getElementById('close-certificate').onclick=()=>certificateDialog.close();document.getElementById('previous-certificate').onclick=()=>stepCertificate(-1);document.getElementById('next-certificate').onclick=()=>stepCertificate(1);certificateDialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();stepCertificate(1)}if(e.key==='ArrowLeft'){e.preventDefault();stepCertificate(-1)}});certificateDialog.addEventListener('click',e=>{if(e.target===certificateDialog){const r=certificateDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)certificateDialog.close()}});
const cards=[...document.querySelectorAll('.cert-card')];const reduceCertificateMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let certificateObserver;if('IntersectionObserver' in window&&!reduceCertificateMotion.matches){document.querySelector('.certificate-gallery').classList.add('gather-animation');certificateObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('gathered');certificateObserver.unobserve(entry.target)}})},{threshold:.1});cards.forEach(card=>certificateObserver.observe(card))}
document.querySelectorAll('[data-cert-filter]').forEach(b=>b.onclick=()=>{activeCertificateFilter=b.dataset.certFilter;document.querySelectorAll('[data-cert-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));cards.forEach(card=>{card.hidden=activeCertificateFilter!=='all'&&card.dataset.certGroup!==activeCertificateFilter;if(!card.hidden)card.classList.add('gathered')});const n=visibleCertificates().length;document.getElementById('cert-count').textContent=`${n} ${n===1?'certificate':'certificates'} on the wall.`});
const finePointer=window.matchMedia('(hover: hover) and (pointer: fine)');const cursorToggle=document.getElementById('cursor-toggle');let scannerEnabled=true;try{scannerEnabled=localStorage.getItem('fouad-cursor')!=='native'}catch{}function applyScanner(){document.documentElement.classList.toggle('scanner-cursor',scannerEnabled&&finePointer.matches);cursorToggle.setAttribute('aria-pressed',scannerEnabled);cursorToggle.textContent=scannerEnabled?'Cursor: scanner ⌖':'Cursor: classic ↖'}cursorToggle.onclick=()=>{scannerEnabled=!scannerEnabled;try{localStorage.setItem('fouad-cursor',scannerEnabled?'scanner':'native')}catch{}applyScanner()};finePointer.addEventListener('change',applyScanner);applyScanner();
